import { test, expect } from '@playwright/test';

test.describe('Filter Result Counts', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should display result counts for each filter option', async ({ page }) => {
    // Verify search input is visible
    const searchInput = page.getByPlaceholder('Search...');
    await expect(searchInput).toBeVisible();

    // Verify filter options container is visible
    const filterContainer = page.getByRole('region', { name: /filters/i });
    await expect(filterContainer).toBeVisible();

    // Verify result count display is visible
    const resultCount = page.getByText(/results found/i);
    await expect(resultCount).toBeVisible();

    // Verify filter options are displayed with counts
    const filterOptions = page.getByRole('option');
    const filterCount = page.getByText(/\d+ results/i);
    await expect(filterOptions).toHaveCount(3);
    await expect(filterCount).toBeVisible();

    // Verify filter options have count labels
    const filterOption1 = page.getByRole('option', { name: /category/i });
    const countLabel1 = page.getByText(/12 results/i);
    await expect(countLabel1).toBeVisible();

    const filterOption2 = page.getByRole('option', { name: /price range/i });
    const countLabel2 = page.getByText(/5 results/i);
    await expect(countLabel2).toBeVisible();

    const filterOption3 = page.getByRole('option', { name: /date added/i });
    const countLabel3 = page.getByText(/2 results/i);
    await expect(countLabel3).toBeVisible();

    // Verify filter options are clickable
    await expect(filterOption1).toBeEnabled();
    await expect(filterOption2).toBeEnabled();
    await expect(filterOption3).toBeEnabled();

    // Click on a filter option to verify count updates
    await filterOption1.click();
    await expect(countLabel1).toBeVisible();
    await expect(resultCount).toContainText('12 results found');
  });

  test('should handle no results when filter options have zero count', async ({ page }) => {
    // Navigate to a page with no results
    await page.goto('/search?q=nonexistentquery');

    // Verify no results message is displayed
    const noResultsMessage = page.getByText(/no results found/i);
    await expect(noResultsMessage).toBeVisible();

    // Verify filter options are still displayed
    const filterContainer = page.getByRole('region', { name: /filters/i });
    await expect(filterContainer).toBeVisible();

    // Verify filter options are visible but have zero count
    const filterOptions = page.getByRole('option');
    await expect(filterOptions).toHaveCount(3);

    const filterOption1 = page.getByRole('option', { name: /category/i });
    const countLabel1 = page.getByText(/0 results/i);
    await expect(countLabel1).toBeVisible();

    const filterOption2 = page.getByRole('option', { name: /price range/i });
    const countLabel2 = page.getByText(/0 results/i);
    await expect(countLabel2).toBeVisible();

    // Verify result count shows zero
    const resultCount = page.getByText(/0 results found/i);
    await expect(resultCount).toBeVisible();

    // Verify filter options are still clickable
    await expect(filterOption1).toBeEnabled();
    await expect(filterOption2).toBeEnabled();
  });
});
